import mongoose from 'mongoose';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

// A service / maintenance (AMC) contract with a company. The company's details
// stay on the company; the contract references it and its customer record.
const contractSchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    contractNumber: { type: String, required: true, unique: true, immutable: true },
    companyId: { type: ObjectId, ref: 'Company', required: true, index: true },
    // The company's customer record, filled in by the server when there is one.
    customerId: { type: ObjectId, ref: 'Customer', index: true },
    contractTypeId: { type: ObjectId, ref: 'ContractType', index: true },
    startDate: { type: Date, required: true },
    endDate: { type: Date, required: true, index: true },
    // The contract value for its whole term.
    amount: { type: Number, required: true, min: 0 },
    billingCycleId: { type: ObjectId, ref: 'BillingCycle', index: true },
    statusId: { type: ObjectId, ref: 'ContractStatus', required: true, index: true },
    assignedTo: { type: ObjectId, ref: 'User', index: true },
    // When renewal is due to be taken up with the customer.
    renewalDate: { type: Date, index: true },
    description: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        companyId: 'company',
        customerId: 'customer',
        contractTypeId: 'contractType',
        billingCycleId: 'billingCycle',
        statusId: 'status',
        assignedTo: 'assignedToUser',
        createdBy: 'createdByUser',
      },
    }),
  }
);

softDelete(contractSchema);

// Found by global search on these fields.
searchable(contractSchema, ['contractNumber']);

export default mongoose.model('Contract', contractSchema);
